const fs = require('fs');
const { JSDOM } = require('jsdom');

const SRC = process.argv[2];
const DISABLE_ANTICHOP = process.argv[3] !== 'keep-antichop';
const MAX_RUN_MS = Number(process.argv[4] || 15000);

let code = fs.readFileSync(SRC, 'utf8');
if (DISABLE_ANTICHOP) {
  // ปิดเฉพาะโหมดแทงลม เพื่อให้เทสต์เดินไม้จริงได้ถึงเพดาน (โหมดนี้จะสลับไปแทงลมก่อนถึงไม้ 19 ถ้าแพ้รวด)
  const before = code;
  code = code.replace('let configVirtualBetEnabled = true;', 'let configVirtualBetEnabled = false;');
  if (code === before) throw new Error('fault-injection failed: configVirtualBetEnabled not found');
}

const html = `<!doctype html><html><body>
<span data-testid="balance">1000.00000000</span>
<input data-testid="amount" value="0.001">
<input data-testid="chance" value="49">
<button data-testid="bet-button">Bet</button>
</body></html>`;

const dom = new JSDOM(html, { runScripts: 'outside-only', pretendToBeVisual: true, url: 'https://stake.com/casino/games/dice' });
const w = dom.window;

// ให้อ่าน HUD ได้ (โค้ดใช้ closed shadow DOM)
const origAttach = w.Element.prototype.attachShadow;
w.Element.prototype.attachShadow = function (init) {
  return origAttach.call(this, { ...init, mode: 'open' });
};

// fetch/Response ของ Node ให้โค้ด hook ได้เหมือนเบราว์เซอร์
w.Response = globalThis.Response;
w.Request = globalThis.Request;
w.Headers = globalThis.Headers;

let bets = [];
w.fetch = async function (url) {
  const amount = parseFloat(w.document.querySelector('[data-testid="amount"]').value);
  bets.push(amount);
  // ทุกตาออกแพ้: payoutMultiplier = 0
  return new globalThis.Response(JSON.stringify({
    data: { diceRoll: { id: String(bets.length), amount, payoutMultiplier: 0, state: { result: 99.9, condition: 'below', target: 49 } } }
  }), { status: 200, headers: { 'content-type': 'application/json' } });
};

// หน้าเว็บจำลอง: กดปุ่ม Bet แล้วยิง fetch (แบบที่เว็บ Stake จริงทำ)
w.document.querySelector('[data-testid="bet-button"]').addEventListener('click', () => {
  w.fetch('/_api/casino/dice/roll', { method: 'POST' });
});

w.eval(code);

function hudText() {
  const hosts = Array.from(w.document.body.children);
  for (const h of hosts) {
    if (h.shadowRoot) return h.shadowRoot.textContent.replace(/\s+/g, ' ').slice(0, 400);
  }
  return '(no HUD)';
}

const t0 = Date.now();
const timer = setInterval(() => {
  if (Date.now() - t0 < MAX_RUN_MS) return;
  clearInterval(timer);
  const hud = hudText();
  console.log('--- ' + SRC.split(/[\\/]/).pop() + ' ---');
  console.log('จำนวนไม้ที่วางเงินจริง:', bets.length);
  console.log('ยอดที่วาง (USD):', bets.map(b => (b === 0 ? '0(virtual)' : b)).join(', '));
  console.log('ไม้สุดท้ายที่วาง:', bets[bets.length - 1]);
  console.log('HUD:', hud || '(ว่าง)');
  console.log('ผลลัพธ์:', bets.length === 19 ? 'PASS — หยุดที่ไม้ 19 ไม่มีไม้ 20' : 'CHECK — จำนวนไม้ = ' + bets.length);
  process.exit(0);
}, 200);
