const fs = require('fs');
const { JSDOM, VirtualConsole } = require('jsdom');

const SRC = process.argv[2];
const TARGET_ROLLS = Number(process.argv[3] || 3000);
const MAX_MS = Number(process.argv[4] || 60000);

const code = fs.readFileSync(SRC, 'utf8');

const vc = new VirtualConsole();
const errors = [];
vc.on('jsdomError', (e) => errors.push(String(e.message || e).slice(0, 200)));

const html = `<!doctype html><html><body>
<span data-testid="wallet-balance">1000.00000000</span>
<input data-testid="input-game-amount" value="0.00029">
<input data-testid="chance" value="49">
<button data-testid="bet-button">Bet</button>
</body></html>`;

const dom = new JSDOM(html, { runScripts: 'outside-only', pretendToBeVisual: true, url: 'https://stake.com/casino/games/dice', virtualConsole: vc });
const w = dom.window;

const origAttach = w.Element.prototype.attachShadow;
w.Element.prototype.attachShadow = function (init) { return origAttach.call(this, { ...init, mode: 'open' }); };

w.Response = globalThis.Response;
w.fetch = async function () {
  const amount = parseFloat(w.document.querySelector('[data-testid="input-game-amount"]').value);
  const win = Math.random() < 0.49;
  const t = Date.now();
  bets.push({ amount, win, t });
  return new globalThis.Response(JSON.stringify({
    data: { diceRoll: { id: String(bets.length), amount, payoutMultiplier: win ? 2.0204 : 0, state: { result: win ? 10 : 90, condition: 'below', target: 49 } } }
  }), { status: 200, headers: { 'content-type': 'application/json' } });
};
const bets = [];

w.document.querySelector('[data-testid="bet-button"]').addEventListener('click', () => { w.fetch('/_api/casino/dice/roll', { method: 'POST' }); });

// เก็บ error จากในหน้า
w.addEventListener('error', (e) => errors.push('window.onerror: ' + String(e.message).slice(0, 200)));

w.eval(code);

function hudText() {
  for (const h of Array.from(w.document.body.children)) if (h.shadowRoot) return h.shadowRoot.textContent.replace(/\s+/g, ' ');
  return '';
}
function clickStart() {
  for (const h of Array.from(w.document.body.children)) {
    if (!h.shadowRoot) continue;
    const b = Array.from(h.shadowRoot.querySelectorAll('button')).find(x => /START/i.test(x.textContent || ''));
    if (b) { b.click(); return true; }
  }
  return false;
}
setTimeout(clickStart, 2500);

const t0 = Date.now();
const iv = setInterval(() => {
  if (bets.length === 0 && Date.now() - t0 > 6000) clickStart();
  if (bets.length < TARGET_ROLLS && Date.now() - t0 < MAX_MS) return;
  clearInterval(iv);

  // หา stall: ช่วงห่างระหว่างตาที่เกิน 1.5 วินาที (ไม่นับช่วงเริ่มต้น)
  let maxGap = 0, stalls = 0;
  for (let i = 1; i < bets.length; i++) {
    const g = bets[i].t - bets[i - 1].t;
    if (g > maxGap) maxGap = g;
    if (g > 1500) stalls++;
  }
  const virtual = bets.filter(b => b.amount === 0).length;
  const real = bets.length - virtual;
  const hud = hudText();
  const capped = /HARD STOP/.test(hud);
  const elapsed = (Date.now() - t0) / 1000;

  console.log('--- ' + SRC.split(/[\\/]/).pop() + ' ---');
  console.log('เวลารวม:', elapsed.toFixed(1), 'วินาที | ตาทั้งหมด:', bets.length);
  console.log('ความเร็วเฉลี่ย:', (bets.length / elapsed).toFixed(1), 'ตา/วินาที');
  console.log('ไม้เงินจริง:', real, '| ไม้แทงลม 0$:', virtual);
  console.log('ช่วงค้าง >1.5s:', stalls, 'ครั้ง | ช่วงห่างมากสุด:', maxGap, 'ms');
  console.log('Error:', errors.length, errors.slice(0, 2));
  console.log('HARD STOP ทำงาน:', capped ? 'ใช่' : 'ไม่');
  console.log('ผลลัพธ์:', (errors.length === 0 && stalls === 0) ? 'PASS — ไม่มี error และไม่ค้าง' : 'CHECK');
  process.exit(0);
}, 200);
