{"kind":"tool","id":"l7jWJpUxkgw","toolName":"write_file","input":{"path":"/tmp/sniper-harness/reject-zero.js","instructions":"Test that the bot stops instead of looping forever when the site never responds to zero-amount bets","content":"// จำลองเว็บที่ไม่ตอบสนองต่อยอด 0$ (แทงลม) แล้วดูว่าบอทหยุดหรือวนไม่จำกัด
const fs = require('fs');
const { JSDOM, VirtualConsole } = require('jsdom');

const SRC = process.argv[2];
const RUN_MS = Number(process.argv[3] || 25000);
const code = fs.readFileSync(SRC, 'utf8');

const vc = new VirtualConsole();
const vcErrors = [];
vc.on('jsdomError', (e) => vcErrors.push(String(e.message || e).slice(0, 120)));

const dom = new JSDOM(`<!doctype html><html><body>
<span data-testid="wallet-balance">1000.00000000</span>
<input data-testid="input-game-amount" value="0.00029">
<input data-testid="chance" value="49">
<button data-testid="bet-button">Bet</button>
</body></html>`, { runScripts: 'outside-only', pretendToBeVisual: true, url: 'https://stake.com/casino/games/dice', virtualConsole: vc });
const w = dom.window;

const origAttach = w.Element.prototype.attachShadow;
w.Element.prototype.attachShadow = function (init) { return origAttach.call(this, { ...init, mode: 'open' }); };
w.Response = globalThis.Response;

let realBets = 0, zeroBets = 0;
w.fetch = async function () {
  const amount = parseFloat(w.document.querySelector('[data-testid="input-game-amount"]').value);
  if (amount === 0) {
    zeroBets++;
    // เว็บไม่ตอบสนองเลย: promise ค้างตลอดกาล (จำลองการปฏิเสธยอด 0$)
    return new Promise(() => {});
  }
  realBets++;
  // ไม้เงินจริง: แพ้รวด เพื่อให้ไปถึงเงื่อนไขเข้าโหมดแทงลมเร็วที่สุด
  return new globalThis.Response(JSON.stringify({
    data: { diceRoll: { id: String(realBets), amount, payoutMultiplier: 0, state: { result: 99, condition: 'below', target: 49 } } }
  }), { status: 200, headers: { 'content-type': 'application/json' } });
};
w.document.querySelector('[data-testid="bet-button"]').addEventListener('click', () => { w.fetch('/_api/casino/dice/roll', { method: 'POST' }); });

w.eval(code);

function statusText() {
  for (const h of Array.from(w.document.body.children)) {
    if (!h.shadowRoot) continue;
    const el = h.shadowRoot.getElementById('sniperStatusText');
    if (el) return el.textContent || '';
  }
  return '';
}
function clickStart() {
  for (const h of Array.from(w.document.body.children)) {
    if (!h.shadowRoot) continue;
    const b = Array.from(h.shadowRoot.querySelectorAll('button')).find(x => /START/i.test(x.textContent || ''));
    if (b) { b.click(); return true; }
  }
  return false;
}
setTimeout(clickStart, 2500);

const samples = [];
setInterval(() => { samples.push({ t: Date.now(), real: realBets, zero: zeroBets, s: statusText() }); }, 500);

setTimeout(() => {
  const last = samples[samples.length - 1];
  const stopped = /ไม่ตอบสนอง|หยุด/.test(last.s);
  // นับจำนวนการยิง 0$ หลังสถานะหยุดครั้งแรก
  const stopIdx = samples.findIndex(x => /ไม่ตอบสนอง/.test(x.s));
  const zeroAtStop = stopIdx >= 0 ? samples[stopIdx].zero : null;
  const zeroAfter = stopIdx >= 0 ? last.zero - zeroAtStop : null;

  console.log('--- ' + SRC.split(/[\\/]/).pop() + ' ---');
  console.log('ไม้เงินจริง:', realBets, '| ไม้ 0$ ที่ยิงออก:', zeroBets);
  console.log('สถานะสุดท้าย:', last.s.slice(0, 110));
  console.log('หยุดสำเร็จ:', stopped ? 'ใช่' : 'ไม่');
  if (stopIdx >= 0) console.log('หลังหยุดแล้วยังยิง 0$ เพิ่มอีก:', zeroAfter, 'ครั้ง');
  console.log('error:', vcErrors.length);
  console.log('ผลลัพธ์:', stopped && (zeroAfter === 0) ? 'PASS — หยุดและไม่วนต่อ' : 'FAIL — ยังวน/ไม่หยุด');
  process.exit(0);
}, RUN_MS);
"}}


