    status = r.getElementById('sniperStatusText').textContent;
    if (/HARD STOP/.test(status)) break;
    await sleep(50);
  }
  const stepLabel = r.getElementById('sniperMiniStep') ? r.getElementById('sniperMiniStep').textContent : '';
  check('hard stopped at the tuned cap', /HARD STOP/.test(status), status.trim());
  check('stop message names 18 steps', /18/.test(status), status.trim());
