    <input data-testid="chance" />
    <button data-testid="bet-button">Bet</button>
  </div>
</body></html>`;

const dom = new JSDOM(page, {
  url: 'https://stake.com/th/casino/games/dice',
  runScripts: 'dangerously',
  pretendToBeVisual: true,
});
const { window } = dom;
const origAttach = window.Element.prototype.attachShadow;
window.Element.prototype.attachShadow = function (init) {
  return origAttach.call(this, Object.assign({}, init, { mode: 'open' }));
};

// rolls are WINS, but the DOM balance stays 3.0000000 -> desync
let rolls = 0;
class FakeXHR {
  constructor() { this._listeners = {}; this.responseText = ''; this.readyState = 0; }
  open(m, u) { this._url = u; this.readyState = 1; }
  addEventListener(t, fn) { (this._listeners[t] = this._listeners[t] || []).push(fn); }
  send() {
    rolls++;
    setTimeout(() => {
      this.readyState = 4;
      this.responseText = JSON.stringify({
        data: { diceRoll: { payoutMultiplier: 99 / 49, amount: 0.0001, state: { result: 10 } } },
      });
      (this._listeners['load'] || []).forEach((f) => f.call(this));
    }, 10);
  }
}
window.XMLHttpRequest = FakeXHR;

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
window.eval(src);

const betBtn = window.document.querySelector('[data-testid="bet-button"]');
betBtn.addEventListener('click', () => {
  const x = new window.XMLHttpRequest();
  x.open('POST', '/_api/dice/roll');
  x.send();
});

const root = () => {
  const host = [...window.document.body.children].find((el) => el.shadowRoot);
  return host ? host.shadowRoot : null;
};

(async () => {
  let fails = 0;
