  check('HUD ready (AUTO tuned to 18 steps)', !!r);
  if (!r) process.exit(1);

  // theory line exists and shows real numbers
  const theory = r.getElementById('sniperTheory');
  check('theory line exists', !!theory);

  let status = '';
  for (let i = 0; i < 400; i++) {
