    if (/DESYNC/.test(status)) break;
    await sleep(50);
  }
  check('stopped on DESYNC', /DESYNC/.test(status), status.trim());
  check('desync detected after 3 strikes', /3 ครั้งติด/.test(status), status.trim());
  check('bet attempts bounded (no runaway)', rolls <= 8, 'rolls=' + rolls);

  const before = rolls;
  await sleep(1200);
  check('no bets after desync stop', rolls === before, 'rolls=' + rolls);

  const t = theory.textContent;
  check('theory line has real winrate', /จริง\s+[\d.]+%/.test(t), t);
  check('theory line shows 49% benchmark', /ทฤษฎี 49%/.test(t), '');
  check('theory line shows EV and placed volume', /EV คาด/.test(t) && /วาง/.test(t), '');

  console.log(fails === 0 ? '\nALL OK' : '\nFAILURES ' + fails);
  process.exit(fails ? 1 : 0);
})();
"}}


