    </div>
  </body></html>`;
  const dom = new JSDOM(page, { url: 'https://stake.com/th/casino/games/dice', runScripts: 'dangerously', pretendToBeVisual: true });
  const { window } = dom;
  const origAttach = window.Element.prototype.attachShadow;
  window.Element.prototype.attachShadow = function (init) {
    return origAttach.call(this, Object.assign({}, init, { mode: 'open' }));
  };
  return { dom, window };
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const rootOf = (window) => {
  const host = [...window.document.body.children].find((el) => el.shadowRoot);
  return host ? host.shadowRoot : null;
};

(async () => {
  let fails = 0;
  const check = (n, c, extra = '') => {
    if (c) console.log('OK   ' + n + (extra ? ' | ' + extra : ''));
    else { fails++; console.log('FAIL ' + n + (extra ? ' | ' + extra : '')); }
  };

  // ---------- A: min attribute is respected ----------
  {
    const { window } = makeDom('min="0.0002" max="5"');
    window.eval(src);
    for (let i = 0; i < 200 && !(rootOf(window) && /18-STEP|16-STEP/.test((rootOf(window).getElementById('sniperTitleStep') || {}).textContent || '')); i++) await sleep(50);
    const r = rootOf(window);
    const title = r.getElementById('sniperTitleStep').textContent;
    const base = r.getElementById('sniperInRealBase').value;
    check('min=0.0002 respected -> 16 steps', /16-STEP/.test(title), title);
    check('base >= detected min', parseFloat(base) >= 0.0002, base);
    const theory = r.getElementById('sniperTheory').textContent;
    check('HUD shows detected limits', /เว็บ: ขั้นต่ำ 0\.0002/.test(theory), theory.slice(-60));
  }

  // ---------- B: kill switch ----------
  {
    const { window } = makeDom('');
    // losing rolls; balance on screen decreases for real
    let rolls = 0;
    class FakeXHR {
      constructor() { this._l = {}; this.responseText = ''; }
      open(m, u) { this._u = u; }
      addEventListener(t, fn) { (this._l[t] = this._l[t] || []).push(fn); }
      send() {
        rolls++;
        setTimeout(() => {
          this.responseText = JSON.stringify({ data: { diceRoll: { payoutMultiplier: 0, amount: 0.0001, state: { result: 90 } } } });
          (this._l['load'] || []).forEach((f) => f.call(this));
        }, 10);
      }
    }
    window.XMLHttpRequest = FakeXHR;
    window.eval(src);

    const balSpan = window.document.querySelector('span[data-ds-text="true"][style*="max-width"]');
    const betBtn = window.document.querySelector('[data-testid="bet-button"]');
    betBtn.addEventListener('click', () => {
      const amt = parseFloat(window.document.querySelector('[data-testid="input-game-amount"]').value) || 0;
      setTimeout(() => {
        const cur = parseFloat(balSpan.textContent) || 0;
        balSpan.textContent = (cur - amt).toFixed(7);
      }, 5);
      const x = new window.XMLHttpRequest();
      x.open('POST', '/_api/dice/roll');
      x.send();
    });

    for (let i = 0; i < 200 && !(rootOf(window) && /18-STEP/.test((rootOf(window).getElementById('sniperTitleStep') || {}).textContent || '')); i++) await sleep(50);
    const r = rootOf(window);

    // set the kill switch to 0.5$ via the HUD input
    const lossInput = r.getElementById('sniperInMaxLoss');
    check('kill-switch input exists', !!lossInput, lossInput ? lossInput.value : '');
    lossInput.value = '0.5';
    lossInput.dispatchEvent(new window.Event('input', { bubbles: true }));

    let status = '';
    for (let i = 0; i < 500; i++) {
      status = r.getElementById('sniperStatusText').textContent;
      if (/ตัดขาดทุน/.test(status)) break;
      await sleep(50);
    }
    check('kill switch stopped the session', /ตัดขาดทุน/.test(status), status.trim());
    check('loss stayed near the cap', rolls > 0 && rolls < 18, 'rolls=' + rolls);

    const before = rolls;
    await sleep(1200);
    check('no bets after kill switch', rolls === before, 'rolls=' + rolls);
  }

  console.log(fails === 0 ? '\nALL OK' : '\nFAILURES ' + fails);
  process.exit(fails ? 1 : 0);
})();
